insert into hub_translations(hub_id,locale,name,summary,story,meeting_point,open_hours,entry_note) select id,'vi','TriGiao Hub – Hồ Hoàn Kiếm','Phố nghề, quán nhỏ và những câu chuyện của người sống quanh hồ.','Mỗi con phố giữ một phần ký ức về nghề và về cách người Hà Nội sống cùng nhau.','Quán Conifer Bốn Mùa - Four Seasons, ven hồ Hoàn Kiếm.','Giờ Hub đang cập nhật',null from hubs where slug='ho-guom' on conflict do nothing;
insert into hub_translations(hub_id,locale,name,summary,story,meeting_point,open_hours,entry_note) select id,'en','TriGiao Hub – Hoan Kiem Lake','Craft streets, small cafés and stories from people who live around the lake.','Each street keeps a piece of memory about trades and about how Hanoians live together.','Conifer Bốn Mùa - Four Seasons café, by Hoan Kiem Lake.','Hub hours to be announced',null from hubs where slug='ho-guom' on conflict do nothing;
