insert into hub_translations(hub_id,locale,name,summary,story,meeting_point,open_hours,entry_note) select id,'vi','TriGiao Hub – Văn Miếu Quốc Tử Giám','Nơi gặp nhau để nói về học vấn, mỹ thuật, chữ nghĩa và cách người Việt trọng tri thức.','Ngay cạnh Văn Miếu, Hub đặt tại tầng 5 Bảo tàng Mỹ thuật Việt Nam. Hub không liên kết với đơn vị quản lý di tích Văn Miếu.','Tầng 5, Bảo tàng Mỹ thuật Việt Nam.','Theo giờ mở cửa của bảo tàng','Có thể cần vé vào bảo tàng.' from hubs where slug='van-mieu' on conflict do nothing;
insert into hub_translations(hub_id,locale,name,summary,story,meeting_point,open_hours,entry_note) select id,'en','TriGiao Hub – Van Mieu Quoc Tu Giam','A place to talk about learning, fine arts, script and how Vietnam honors knowledge.','Next to the Temple of Literature, this Hub is on the 5th floor of the Vietnam National Fine Arts Museum. It is not affiliated with the Temple of Literature management.','5th floor, Vietnam National Fine Arts Museum.','Museum opening hours','A museum ticket may be required.' from hubs where slug='van-mieu' on conflict do nothing;
