insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-01','lobachevsky','Nikolai Lobachevsky',1792,12,1,1856,'math','portrait','lobachevsky.webp','Nhà toán học Nga dám nghi ngờ tiên đề đường song song của Euclid.','Năm 1829 ông công bố hình học phi Euclid, mở ra cách nghĩ mới về không gian.','Russian mathematician who dared to question Euclid’s parallel postulate.','In 1829 he published non-Euclidean geometry, opening a new way of thinking about space.',null,null,null,null,true,'Tam giác trên mặt yên ngựa','Ngày 1/12 theo lịch Gregory (20/11 theo lịch Julius).') on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-02','seurat','Georges Seurat',1859,12,2,1891,'art','portrait','seurat.webp','Họa sĩ Pháp vẽ tranh bằng hàng nghìn chấm màu nhỏ.','Ông khởi xướng lối vẽ chấm điểm. Kiệt tác: Một chiều Chủ nhật trên đảo La Grande Jatte (1884–1886).','French painter who built pictures from thousands of tiny dots.','He pioneered pointillism. Masterpiece: A Sunday Afternoon on the Island of La Grande Jatte (1884–1886).',null,null,null,null,true,'Bờ sông vẽ bằng hàng nghìn chấm màu',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-03','conrad','Joseph Conrad',1857,12,3,1924,'literature','portrait','conrad.webp','Thủy thủ gốc Ba Lan học tiếng Anh khi đã trưởng thành, rồi thành đại văn hào Anh.','Tác phẩm tiêu biểu: Tâm bóng tối (1899) và Lord Jim (1900).','A Polish-born sailor who learned English as an adult and became a great English novelist.','Best known for Heart of Darkness (1899) and Lord Jim (1900).',null,null,null,null,true,'Con tàu buồm trên dòng sông rậm rạp',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-04','rilke','Rainer Maria Rilke',1875,12,4,1926,'literature','portrait','rilke.webp','Nhà thơ viết tiếng Đức, tác giả những lá thư nổi tiếng gửi một nhà thơ trẻ.','Bi ca Duino (1923) được xem là một đỉnh cao của thơ ca thế kỷ 20.','German-language poet, author of famous letters to a young poet.','The Duino Elegies (1923) are considered a summit of 20th-century poetry.','Leben Sie jetzt die Fragen.','Hãy sống với những câu hỏi ngay lúc này.','Live the questions now.','Thư gửi nhà thơ trẻ, 16/7/1903',true,'Lá thư và cánh cửa sổ mở',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-05','heisenberg','Werner Heisenberg',1901,12,5,1976,'physics','symbol','heisenberg.webp','Nhà vật lý Đức gắn với một "nguyên lý" về giới hạn của phép đo.','Ông đặt nền móng cho cơ học lượng tử dạng ma trận (1925) và phát biểu nguyên lý bất định (1927). Giải Nobel Vật lý 1932.','German physicist known for a “principle” about the limits of measurement.','He founded matrix mechanics (1925) and stated the uncertainty principle (1927). Nobel Prize in Physics 1932.',null,null,null,null,true,'Một hạt nhòe thành đám mây xác suất',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-06','gay-lussac','Joseph Louis Gay-Lussac',1778,12,6,1850,'chemistry','portrait','gay-lussac.webp','Nhà hóa học Pháp từng bay khinh khí cầu lên cao hơn 7.000 m để lấy mẫu không khí.','Ông tìm ra định luật về tỉ lệ thể tích của các khí khi phản ứng (1808) và góp phần phát hiện nguyên tố bo.','French chemist who rose by balloon above 7,000 m to sample the air.','He found the law of combining volumes of gases (1808) and helped discover the element boron.',null,null,null,null,true,'Khinh khí cầu và bình thủy tinh lấy mẫu khí',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-07','bernini','Gian Lorenzo Bernini',1598,12,7,1680,'art','portrait','bernini.webp','Nhà điêu khắc, kiến trúc sư làm nên diện mạo Baroque của thành Rome.','Ông thiết kế quảng trường Thánh Phêrô với hàng cột ôm vòng cung và tạc tượng Cực lạc của Thánh Teresa.','Sculptor and architect who shaped Baroque Rome.','He designed St Peter’s Square with its embracing colonnades and carved The Ecstasy of Saint Teresa.',null,null,null,null,true,'Hàng cột vòng cung của quảng trường',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-08','sibelius','Jean Sibelius',1865,12,8,1957,'music','symbol','sibelius.webp','Nhà soạn nhạc trở thành biểu tượng văn hóa của Phần Lan.','Bản giao hưởng thơ Finlandia (1899–1900) trở thành biểu tượng của tinh thần dân tộc Phần Lan.','Composer who became a cultural symbol of Finland.','His tone poem Finlandia (1899–1900) became a symbol of Finnish national spirit.',null,null,null,null,true,'Rừng thông, mặt hồ và khuông nhạc',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-09','milton','John Milton',1608,12,9,1674,'literature','portrait','milton.webp','Nhà thơ Anh đọc cho người khác chép lại thiên sử thi lớn nhất của mình khi đã mù.','Thiên đường đã mất (1667) là trường ca lớn của văn học Anh. Ông cũng viết Areopagitica (1644) bảo vệ tự do in ấn.','English poet who dictated his greatest epic after going blind.','Paradise Lost (1667) is a great English epic. He also wrote Areopagitica (1644) in defence of a free press.',null,null,null,null,true,'Ngọn nến và trang trường ca',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-10','lovelace','Ada Lovelace',1815,12,10,1852,'math','portrait','lovelace.webp','Nữ bá tước Anh viết thuật toán cho một cỗ máy chưa từng được chế tạo xong.','Trong ghi chú năm 1843 về Máy Giải tích của Charles Babbage, bà trình bày cách máy tính các số Bernoulli, thường được xem là chương trình máy tính đầu tiên.','English countess who wrote an algorithm for a machine that was never finished.','In her 1843 notes on Charles Babbage’s Analytical Engine she showed how it could compute Bernoulli numbers, often called the first computer program.','The Analytical Engine weaves algebraical patterns just as the Jacquard-loom weaves flowers and leaves.','Máy Giải tích dệt nên những hoa văn đại số, như khung cửi Jacquard dệt hoa và lá.','The Analytical Engine weaves algebraical patterns just as the Jacquard-loom weaves flowers and leaves.','Ghi chú A, 1843',true,'Bánh răng của cỗ máy tính và hoa văn dệt',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-11','koch','Robert Koch',1843,12,11,1910,'medicine','portrait','koch.webp','Bác sĩ Đức tìm ra vi khuẩn gây bệnh lao.','Năm 1882 ông công bố vi khuẩn lao; ông cũng xác định vi khuẩn gây bệnh than và bệnh tả. Giải Nobel Y học 1905.','German physician who identified the bacterium that causes tuberculosis.','He announced the tuberculosis bacterium in 1882 and also identified the causes of anthrax and cholera. Nobel Prize in Medicine 1905.',null,null,null,null,true,'Kính hiển vi và đĩa nuôi cấy',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-12','flaubert','Gustave Flaubert',1821,12,12,1880,'literature','portrait','flaubert.webp','Nhà văn Pháp có thể mất cả tuần để chọn đúng một chữ.','Bà Bovary (1857) mở đầu tiểu thuyết hiện thực hiện đại. Ông từng bị đưa ra tòa vì tác phẩm này và được tha bổng.','French writer who could spend a week searching for the right word.','Madame Bovary (1857) helped launch the modern realist novel. He was put on trial over it and acquitted.',null,null,null,null,true,'Bàn viết với những trang bị gạch xóa',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-13','siemens','Werner von Siemens',1816,12,13,1892,'engineering','portrait','siemens.webp','Kỹ sư, nhà sáng lập một tập đoàn điện của Đức.','Năm 1847 ông đồng sáng lập hãng Siemens & Halske, xây dựng mạng điện báo, và năm 1866 phát triển máy phát điện tự kích.','Engineer and founder of a German electrical company.','He co-founded Siemens & Halske in 1847, built telegraph networks and in 1866 developed the self-excited dynamo.',null,null,null,null,true,'Máy phát điện và dây điện báo',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-14','tycho','Tycho Brahe',1546,12,14,1601,'astronomy','portrait','tycho.webp','Nhà thiên văn Đan Mạch đo vị trí sao chính xác nhất thời chưa có kính thiên văn.','Năm 1572 ông quan sát một "ngôi sao mới" (siêu tân tinh), cho thấy bầu trời không bất biến. Dữ liệu của ông giúp Kepler tìm ra các định luật chuyển động hành tinh.','Danish astronomer who made the most precise naked-eye star measurements.','In 1572 he observed a “new star” (a supernova), showing the heavens can change. His data let Kepler find the laws of planetary motion.',null,null,null,null,true,'Thước đo góc khổng lồ dưới bầu trời sao','Ngày sinh theo lịch Julius.') on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-15','eiffel','Gustave Eiffel',1832,12,15,1923,'engineering','portrait','eiffel.webp','Kỹ sư Pháp; công ty của ông dựng ngọn tháp biểu tượng của Paris.','Tháp Eiffel hoàn thành năm 1889 cho Triển lãm Thế giới. Ông cũng thiết kế khung sắt bên trong tượng Nữ thần Tự do.','French engineer whose company built the symbol of Paris.','The Eiffel Tower was finished in 1889 for the World’s Fair. He also designed the iron frame inside the Statue of Liberty.',null,null,null,null,true,'Khung thép đan chéo của một ngọn tháp',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-16','austen','Jane Austen',1775,12,16,1817,'literature','portrait','austen.webp','Nữ văn sĩ Anh viết về hôn nhân và giai cấp với giọng châm biếm tinh tế.','Kiêu hãnh và định kiến (1813) là một trong những tiểu thuyết được đọc nhiều nhất thế giới.','English novelist who wrote about marriage and class with gentle irony.','Pride and Prejudice (1813) is one of the most widely read novels in the world.','It is a truth universally acknowledged, that a single man in possession of a good fortune, must be in want of a wife.','Ai cũng thừa nhận một sự thật rằng một người đàn ông độc thân có tài sản lớn hẳn đang cần một người vợ.','It is a truth universally acknowledged, that a single man in possession of a good fortune, must be in want of a wife.','Kiêu hãnh và định kiến, 1813',true,'Bàn viết nhỏ và tách trà',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-17','davy','Humphry Davy',1778,12,17,1829,'chemistry','portrait','davy.webp','Nhà hóa học Anh dùng dòng điện để tách ra nhiều nguyên tố mới.','Năm 1807 ông dùng điện phân tách được natri và kali, sau đó là canxi, magie, bari. Ông cũng phát minh đèn an toàn cho thợ mỏ (1815).','English chemist who used electricity to isolate new elements.','In 1807 he isolated sodium and potassium by electrolysis, then calcium, magnesium and barium. He also invented the miners’ safety lamp (1815).',null,null,null,null,true,'Pin điện, bình điện phân và đèn mỏ',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-18','jj-thomson','J. J. Thomson',1856,12,18,1940,'physics','portrait','jj-thomson.webp','Nhà vật lý Anh tìm ra hạt mang điện đầu tiên nhỏ hơn nguyên tử.','Năm 1897 ông phát hiện electron. Giải Nobel Vật lý 1906.','English physicist who found the first particle smaller than an atom.','He discovered the electron in 1897. Nobel Prize in Physics 1906.',null,null,null,null,true,'Ống tia âm cực phát sáng',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-19','michelson','Albert A. Michelson',1852,12,19,1931,'physics','portrait','michelson.webp','Nhà vật lý đo tốc độ ánh sáng chính xác bậc nhất thời của mình.','Thí nghiệm Michelson–Morley (1887) không tìm thấy "ê-te", góp phần mở đường cho thuyết tương đối. Năm 1907 ông là người Mỹ đầu tiên đoạt giải Nobel khoa học.','Physicist who measured the speed of light more precisely than anyone of his time.','The Michelson–Morley experiment (1887) found no “ether”, helping pave the way to relativity. In 1907 he became the first American to win a Nobel Prize in science.',null,null,null,null,true,'Hai chùm sáng giao thoa trên bàn đá',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-20','rickey','Branch Rickey',1881,12,20,1965,'sport','symbol','rickey.webp','Nhà quản lý bóng chày Mỹ đã mở cánh cửa giải nhà nghề cho cầu thủ da màu.','Năm 1945 ông ký hợp đồng với Jackie Robinson; năm 1947 Robinson ra sân cho Brooklyn Dodgers, xóa bỏ rào cản màu da ở giải Major League. Ông cũng lập ra hệ thống đội trẻ (farm system) để đào tạo cầu thủ.','American baseball executive who opened the major leagues to Black players.','In 1945 he signed Jackie Robinson, who took the field for the Brooklyn Dodgers in 1947 and broke Major League Baseball’s colour barrier. He also created the farm system for developing young players.',null,null,null,null,true,'Quả bóng chày, găng bắt bóng và bản hợp đồng trên bàn',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-21','ranke','Leopold von Ranke',1795,12,21,1886,'history','portrait','ranke.webp','Nhà sử học Đức đặt nền cho lối viết sử dựa trên tư liệu gốc.','Ông yêu cầu sử gia làm việc với văn khố và tài liệu gốc, và là người đầu tiên tổ chức seminar sử học ở đại học. Năm 1865 ông được phong tước, từ đó có chữ "von" trong tên.','German historian who grounded the writing of history in original sources.','He required historians to work from archives and primary documents, and was the first to run a history seminar at a university. He was ennobled in 1865, adding "von" to his name.','Er will blos zeigen, wie es eigentlich gewesen.','Tác phẩm này chỉ muốn cho thấy sự việc đã thực sự diễn ra thế nào.','This work merely wants to show how it really was.','Geschichten der romanischen und germanischen Völker, 1824',true,'Chồng hồ sơ lưu trữ và cây bút','Sổ sách ghi ngày 20/12; theo truyền thống gia đình là 21/12 (Neue Deutsche Biographie).') on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-22','ramanujan','Srinivasa Ramanujan',1887,12,22,1920,'math','portrait','ramanujan.webp','Nhà toán học Ấn Độ phần lớn tự học, để lại hàng nghìn công thức.','Năm 1913 ông viết thư cho G. H. Hardy ở Cambridge rồi sang Anh làm việc cùng Hardy. Ông đóng góp lớn về lý thuyết số, chuỗi vô hạn và hàm phân hoạch, được bầu vào Hội Hoàng gia Anh năm 1918. Ấn Độ lấy ngày sinh của ông làm Ngày Toán học Quốc gia.','Largely self-taught Indian mathematician who left thousands of formulas.','In 1913 he wrote to G. H. Hardy in Cambridge and went on to work with him in England. He made major contributions to number theory, infinite series and the partition function, and was elected a Fellow of the Royal Society in 1918. India marks his birthday as National Mathematics Day.',null,null,null,null,true,'Trang sổ tay đầy công thức chuỗi vô hạn',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-23','champollion','Jean-François Champollion',1790,12,23,1832,'linguistics','portrait','champollion.webp','Học giả Pháp giải mã chữ tượng hình Ai Cập.','Năm 1822, dựa vào Phiến đá Rosetta và nhiều văn bản khác, ông công bố cách đọc chữ tượng hình, mở đầu ngành Ai Cập học hiện đại.','French scholar who deciphered Egyptian hieroglyphs.','In 1822, working from the Rosetta Stone and other texts, he published how hieroglyphs could be read, founding modern Egyptology.',null,null,null,null,true,'Phiến đá Rosetta với ba loại chữ',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-24','joule','James Prescott Joule',1818,12,24,1889,'physics','portrait','joule.webp','Nhà vật lý Anh, con nhà nấu bia, đo được đương lượng cơ của nhiệt.','Ông chứng minh công cơ học chuyển thành nhiệt theo một tỉ lệ cố định, góp phần xác lập định luật bảo toàn năng lượng. Đơn vị năng lượng joule (J) mang tên ông.','English physicist and brewer’s son who measured the mechanical equivalent of heat.','He showed that mechanical work turns into heat at a fixed rate, helping establish the conservation of energy. The joule (J), the unit of energy, is named after him.',null,null,null,null,true,'Cánh khuấy trong bình nước nối với quả nặng',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-25','newton','Isaac Newton',1642,12,25,1727,'physics','portrait','newton.webp','Nhà khoa học Anh nêu ra ba định luật chuyển động và định luật vạn vật hấp dẫn.','Tác phẩm Principia (1687) giải thích chuyển động trên Trái Đất và của các thiên thể bằng cùng những định luật. Ông còn nghiên cứu ánh sáng với lăng kính và phát triển phép tính vi tích phân, độc lập với Leibniz. Ngày sinh 25/12 tính theo lịch Julius khi đó ở Anh.','English scientist behind the three laws of motion and universal gravitation.','His Principia (1687) explained motion on Earth and in the heavens with the same laws. He also studied light with prisms and developed calculus independently of Leibniz. The 25 December date is from the Julian calendar then used in England.','If I have seen further it is by standing on the shoulders of Giants.','Nếu tôi nhìn được xa hơn, đó là nhờ đứng trên vai những người khổng lồ.','If I have seen further it is by standing on the shoulders of Giants.','Letter to Robert Hooke, 1675/76',true,'Lăng kính tách ánh sáng và quỹ đạo hành tinh','Ngày 25/12/1642 theo lịch Julius dùng ở Anh lúc đó; theo lịch Gregory là 4/1/1643.') on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-26','babbage','Charles Babbage',1791,12,26,1871,'engineering','portrait','babbage.webp','Nhà toán học Anh thiết kế những cỗ máy tính cơ học đầu tiên.','Ông thiết kế Máy sai phân và Máy giải tích. Máy giải tích có bộ nhớ, bộ xử lý và nhận lệnh bằng thẻ đục lỗ, được xem là ý tưởng sớm nhất về máy tính lập trình được. Ada Lovelace viết các ghi chú nổi tiếng về cỗ máy này năm 1843.','English mathematician who designed the first mechanical computers.','He designed the Difference Engine and the Analytical Engine. The Analytical Engine had a memory, a processor and punched-card instructions, the earliest idea of a programmable computer. Ada Lovelace wrote her famous notes on it in 1843.',null,null,null,null,true,'Các cột bánh răng của Máy sai phân',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-27','hai-thuong-lan-ong','Hải Thượng Lãn Ông',1724,12,27,1791,'medicine','symbol','hai-thuong-lan-ong.webp','Danh y Việt Nam thế kỷ 18, tên thật Lê Hữu Trác, được tôn là Y thánh của Việt Nam.','Ông soạn bộ Hải Thượng y tông tâm lĩnh (海上醫宗心領), viết bằng chữ Hán, gồm 28 tập, 66 quyển: từ lý luận, cách chữa, bài thuốc, vị thuốc đến nội khoa, ngoại khoa, sản phụ khoa, nhi khoa, cấp cứu, đạo đức nghề y và vệ sinh phòng bệnh.','18th-century Vietnamese physician Lê Hữu Trác, honoured as the saint of Vietnamese medicine.','He compiled the Hải Thượng y tông tâm lĩnh (海上醫宗心領), written in classical Chinese in 28 volumes and 66 books, covering medical theory, treatments, prescriptions and herbs, internal and external medicine, obstetrics, paediatrics, emergency care, medical ethics and disease prevention.',null,null,null,null,true,'Trang mở đầu quyển 28 bộ Hải Thượng y tông tâm lĩnh (bản khắc in)','Sinh giờ Dần ngày 12 tháng 11 năm Giáp Thìn theo gia phả họ Lê, tức 27/12/1724; nhiều tài liệu cũ ghi 1720. Ảnh dựng từ bản khắc in, đã bỏ dấu thư viện. Không dùng ảnh chụp lan truyền trên mạng: ông mất năm 1791, trước khi có nhiếp ảnh.') on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-28','eddington','Arthur Eddington',1882,12,28,1944,'astronomy','portrait','eddington.webp','Nhà thiên văn Anh dẫn đoàn quan sát nhật thực năm 1919.','Quan sát nhật thực năm 1919 cho thấy ánh sáng sao bị lệch khi đi gần Mặt Trời, phù hợp với thuyết tương đối rộng của Einstein. Ông cũng đặt nền cho lý thuyết về cấu trúc bên trong các ngôi sao.','English astronomer who led an expedition to the 1919 solar eclipse.','Observations of the 1919 eclipse showed starlight bending near the Sun, as Einstein’s general relativity predicted. He also laid the foundations of the theory of stellar interiors.',null,null,null,null,true,'Nhật thực toàn phần và tia sáng sao bị bẻ cong',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-29','goodyear','Charles Goodyear',1800,12,29,1860,'chemistry','portrait','goodyear.webp','Nhà phát minh Mỹ tự học, tìm ra cách lưu hóa cao su.','Năm 1839 ông phát hiện rằng nung cao su với lưu huỳnh làm cao su bền, không chảy nhão khi nóng và không giòn khi lạnh; ông được cấp bằng sáng chế năm 1844. Hãng lốp Goodyear mang tên ông nhưng không do ông lập ra. Ông mất trong cảnh nghèo khó.','Self-taught American inventor who found how to vulcanize rubber.','In 1839 he found that heating rubber with sulphur made it durable, neither sticky in heat nor brittle in cold; he patented the process in 1844. The Goodyear tyre company is named after him but was not founded by him. He died poor.',null,null,null,null,true,'Bếp lò và tấm cao su lưu hóa',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-30','kipling','Rudyard Kipling',1865,12,30,1936,'literature','portrait','kipling.webp','Nhà văn Anh sinh ở Bombay, tác giả Sách rừng xanh.','Ông viết Sách rừng xanh (1894) và Kim (1901). Năm 1907 ông là nhà văn viết tiếng Anh đầu tiên nhận giải Nobel Văn học. Một số tác phẩm của ông ca ngợi chủ nghĩa đế quốc Anh nên đến nay vẫn gây tranh cãi.','English writer born in Bombay, author of The Jungle Book.','He wrote The Jungle Book (1894) and Kim (1901). In 1907 he became the first English-language writer to win the Nobel Prize in Literature. Some of his work celebrates British imperialism and remains controversial.',null,null,null,null,true,'Khu rừng nhiệt đới và cuốn sách mở','Nhân vật gây tranh cãi vì quan điểm đế quốc. Nội dung chỉ nêu tác phẩm và giải thưởng; admin cân nhắc trước khi bật.') on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('12-31','matisse','Henri Matisse',1869,12,31,1954,'art','symbol','matisse.webp','Họa sĩ Pháp nổi tiếng với màu sắc táo bạo và tranh cắt giấy.','Ông là gương mặt chính của trường phái Dã thú đầu thế kỷ 20. Những năm cuối đời, khi sức khỏe yếu, ông chuyển sang cắt dán giấy màu thành những tác phẩm khổ lớn.','French painter known for bold colour and paper cut-outs.','He was a leading figure of Fauvism in the early 20th century. In his last years, when his health failed, he turned to large works made of cut and pasted coloured paper.',null,null,null,null,true,'Những mảng giấy màu cắt rời và cây kéo',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('11-20','hubble','Edwin Hubble',1889,11,20,1953,'astronomy','symbol','hubble.webp','Nhà thiên văn chỉ ra rằng ngoài Ngân Hà còn vô số thiên hà khác.','Năm 1929 ông công bố mối liên hệ giữa khoảng cách và tốc độ lùi xa của các thiên hà, nay gọi là định luật Hubble–Lemaître, bằng chứng quan trọng cho thấy vũ trụ đang giãn nở. Kính thiên văn không gian Hubble mang tên ông.','The astronomer who showed there are countless galaxies beyond the Milky Way.','In 1929 he published the link between a galaxy’s distance and how fast it recedes, now called the Hubble–Lemaître law, key evidence that the universe is expanding. The Hubble Space Telescope is named after him.',null,null,null,null,true,'Kính thiên văn và các thiên hà xoắn ốc trôi xa nhau',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('11-21','voltaire','Voltaire',1694,11,21,1778,'philosophy','portrait','voltaire.webp','Nhà văn, triết gia Khai sáng người Pháp, tác giả tiểu thuyết Candide.','Ông bảo vệ tự do ngôn luận và khoan dung tôn giáo. Candide (1759) châm biếm thói lạc quan mù quáng.','French Enlightenment writer and philosopher, author of Candide.','He defended free speech and religious tolerance. Candide (1759) mocks blind optimism.','Le mieux est l’ennemi du bien.','Cầu toàn là kẻ thù của điều tốt.','The best is the enemy of the good.','La Bégueule, 1772',true,'Bút lông ngỗng và cuốn Candide',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('11-22','george-eliot','George Eliot',1819,11,22,1880,'literature','portrait','george-eliot.webp','Nữ văn sĩ Anh dùng bút danh nam để tác phẩm được nhìn nhận nghiêm túc.','Tên thật là Mary Ann Evans. Tiểu thuyết Middlemarch (1871–1872) của bà thường được xếp vào hàng tiểu thuyết Anh vĩ đại nhất.','English novelist who wrote under a male pen name to be taken seriously.','Born Mary Ann Evans. Her novel Middlemarch (1871–1872) is often ranked among the greatest English novels.',null,null,null,null,true,'Chồng bản thảo bên ô cửa thị trấn nhỏ nước Anh',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('11-23','falla','Manuel de Falla',1876,11,23,1946,'music','portrait','falla.webp','Nhà soạn nhạc Tây Ban Nha đưa âm hưởng flamenco vào nhạc giao hưởng.','Tác phẩm tiêu biểu: vở ballet Tình yêu phù thủy (El amor brujo) và Chiếc mũ ba góc (El sombrero de tres picos).','Spanish composer who brought flamenco colours into orchestral music.','Best known for the ballets El amor brujo and The Three-Cornered Hat.',null,null,null,null,true,'Cây đàn guitar và khuông nhạc',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('11-24','spinoza','Baruch Spinoza',1632,11,24,1677,'philosophy','portrait','spinoza.webp','Triết gia Hà Lan kiếm sống bằng nghề mài thấu kính.','Tác phẩm Đạo đức học (Ethica), xuất bản sau khi ông mất, trình bày triết học theo lối chứng minh hình học.','Dutch philosopher who earned his living grinding lenses.','His Ethics, published after his death, sets out philosophy in the form of geometric proofs.','Non ridere, non lugere, neque detestari, sed intelligere.','Đừng cười, đừng than khóc, đừng căm ghét, mà hãy hiểu.','Not to laugh, not to lament, not to detest, but to understand.','Tractatus Politicus, I.4',true,'Bàn mài thấu kính và trang sách hình học',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('11-25','carnegie','Andrew Carnegie',1835,11,25,1919,'economy','portrait','carnegie.webp','Từ cậu bé nhập cư nghèo thành "vua thép" của nước Mỹ.','Ông bán công ty thép năm 1901 rồi dành phần lớn tài sản cho từ thiện, tài trợ xây hơn 2.500 thư viện công cộng trên thế giới.','A poor immigrant boy who became America’s “steel king”.','He sold his steel company in 1901 and gave most of his fortune away, funding more than 2,500 public libraries worldwide.',null,null,null,null,true,'Dầm thép và thư viện cổ điển',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('11-26','saussure','Ferdinand de Saussure',1857,11,26,1913,'linguistics','portrait','saussure.webp','Nhà ngôn ngữ học Thụy Sĩ, được xem là cha đẻ của ngôn ngữ học hiện đại.','Giáo trình ngôn ngữ học đại cương (1916), do học trò biên soạn từ bài giảng của ông, đặt nền móng cho chủ nghĩa cấu trúc.','Swiss linguist regarded as the father of modern linguistics.','His Course in General Linguistics (1916), compiled by students from his lectures, laid the foundation of structuralism.',null,null,null,null,true,'Hai mặt của tờ giấy: chữ viết và hình ảnh',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('11-27','celsius','Anders Celsius',1701,11,27,1744,'astronomy','portrait','celsius.webp','Nhà thiên văn Thụy Điển có tên gắn với một thang nhiệt độ.','Năm 1742 ông đề xuất thang 100 độ giữa điểm sôi và điểm đông của nước. Ban đầu thang của ông ngược với ngày nay: 0 là điểm sôi, 100 là điểm đông.','Swedish astronomer whose name is on a temperature scale.','In 1742 he proposed a 100-degree scale between water’s boiling and freezing points. His original scale was upside down: 0 was boiling, 100 was freezing.',null,null,null,null,true,'Nhiệt kế thủy tinh và bầu trời phương Bắc',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('11-28','blake','William Blake',1757,11,28,1827,'literature','portrait','blake.webp','Nhà thơ kiêm họa sĩ Anh, tự khắc và in những tập thơ có minh họa của mình.','Tập Bài ca Ngây thơ và Kinh nghiệm (1789–1794) kết hợp thơ và tranh khắc do chính ông thực hiện.','English poet and painter who engraved and printed his own illustrated books.','Songs of Innocence and of Experience (1789–1794) combines his poems with his own relief etchings.','To see a World in a Grain of Sand / And a Heaven in a Wild Flower','Thấy cả thế giới trong một hạt cát, thấy thiên đường trong một bông hoa dại.','To see a World in a Grain of Sand / And a Heaven in a Wild Flower','Auguries of Innocence',true,'Hạt cát trong lòng bàn tay và bông hoa dại',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('11-29','doppler','Christian Doppler',1803,11,29,1853,'physics','portrait','doppler.webp','Nhà vật lý Áo; hiệu ứng mang tên ông giải thích vì sao tiếng còi đổi cao độ khi xe chạy qua.','Năm 1842 ông mô tả sự thay đổi tần số sóng khi nguồn phát và người nhận chuyển động với nhau. Hiệu ứng Doppler nay dùng trong radar, siêu âm y khoa và thiên văn.','Austrian physicist; his effect explains why a passing siren changes pitch.','In 1842 he described how wave frequency shifts when source and observer move relative to each other. The Doppler effect is used in radar, medical ultrasound and astronomy.',null,null,null,null,true,'Những vòng sóng dồn lại phía trước một đoàn tàu',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values ('11-30','jc-bose','Jagadish Chandra Bose',1858,11,30,1937,'physics','portrait','jc-bose.webp','Nhà khoa học Ấn Độ nghiên cứu cả sóng vô tuyến lẫn đời sống thực vật.','Từ những năm 1890 ông tiên phong nghiên cứu sóng vô tuyến bước sóng milimét, rồi chế tạo máy crescograph đo những chuyển động tăng trưởng rất nhỏ của cây.','Indian scientist who studied both radio waves and plant life.','In the 1890s he pioneered millimetre-wave radio research, and later built the crescograph to measure tiny growth movements of plants.',null,null,null,null,true,'Ăng-ten sóng vô tuyến bên một chậu cây',null) on conflict (id) do nothing;
insert into daily_figures(date,id,name,born_year,born_month,born_day,died_year,field,art,image,vi_hint,vi_fact,en_hint,en_fact,quote_orig,quote_vi,quote_en,quote_src,active,symbol,note) values (null,'nguyen-trai','Nguyễn Trãi',1380,null,null,1442,'literature','symbol','nguyen-trai.webp','Nhà tư tưởng, nhà thơ Việt Nam hiệu Ức Trai (抑齋), tác giả một bản tuyên ngôn nổi tiếng thế kỷ 15.','Ông viết Bình Ngô đại cáo (1428) và Quốc âm thi tập, tập thơ chữ Nôm sớm nhất còn lại. Ông mất ngày 19/9/1442. Năm 1980, UNESCO kỷ niệm 600 năm ngày sinh của ông. Đời sau tôn vinh: "Gặp gỡ long hổ phong vân, còn ghi duyên cũ; truyền tụng văn chương sự nghiệp, để mãi đời sau."','Vietnamese thinker and poet, pen name Ức Trai (抑齋), author of a famous 15th-century proclamation.','He wrote the Great Proclamation upon the Pacification of the Wu (1428) and the earliest surviving collection of poems in Nôm script. He died on 19 September 1442. UNESCO marked his 600th birth anniversary in 1980. A later tribute reads: “His meeting with the ruler was destiny; his writing and deeds are handed down to all generations.”','仁義之舉，要在安民','Việc nhân nghĩa cốt ở yên dân.','The aim of benevolence and righteousness is to bring peace to the people.','Bình Ngô đại cáo, 1428',true,'Các trang khắc in Bình Ngô đại cáo trong Hoàng Việt văn tuyển','Ảnh dựng từ bản khắc in Hoàng Việt văn tuyển (thế kỷ 19). Câu tôn vinh do người gửi cung cấp, dẫn từ Wikipedia tiếng Việt; cần đối chiếu nguồn gốc.') on conflict (id) do nothing;
